export const original118Style = "\n:root{font-family:system-ui,-apple-system,sans-serif;color:#183331;background:#f1f5f3;--ink:#183331;--teal:#097b70;--muted:#60746f}*{box-sizing:border-box}body{margin:0}header{background:#102b2b;color:white;padding:25px max(20px,calc((100vw - 850px)/2));}header small{color:#a4d8cc;letter-spacing:2px;font-weight:700}h1{font-size:29px;margin:7px 0}h2{font-size:20px;margin:0 0 13px}h3{font-size:16px;margin:12px 0}p{line-height:1.5;margin:8px 0}main{max-width:850px;margin:auto;padding:16px 14px 100px}.card{background:white;border:1px solid #dce6e2;border-radius:18px;padding:17px;margin:12px 0;box-shadow:0 2px 8px #24483a08}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric{padding:12px;background:#eaf4ef;border-radius:12px}.metric b{display:block;font-size:26px;letter-spacing:-1px}.muted,small{color:var(--muted);font-size:12px}.meta{font-size:14px;color:var(--muted)}label{display:block;font-size:13px;font-weight:650;margin:10px 0 5px}input,select,textarea{width:100%;border:1px solid #cad9d3;border-radius:10px;padding:11px;background:#fff;color:var(--ink);font:inherit;font-size:16px}textarea{min-height:65px}button{background:var(--teal);color:white;border:0;border-radius:11px;padding:12px 15px;font:inherit;font-weight:650;cursor:pointer}button.secondary{background:#e4efeb;color:#174b42}button.danger{background:#f7e9e6;color:#9d392c}button:disabled{opacity:.5}nav{position:fixed;bottom:0;left:0;right:0;background:white;display:flex;justify-content:center;gap:8px;border-top:1px solid #dce6e2;padding:10px 12px calc(10px + env(safe-area-inset-bottom));z-index:5}nav button{width:min(46%,410px);background:white;color:#526b64}nav button.active{background:#ddefe9;color:#075c50}.hide{display:none!important}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{flex:1}.pill{display:inline-block;font-size:12px;background:#ddefe9;color:#11665b;border-radius:99px;padding:5px 9px}.chart{width:100%;height:auto;display:block}.exercise{border:1px solid #dce6e2;border-radius:14px;padding:12px;margin:10px 0}.exercise summary{cursor:pointer;font-weight:700}.series{display:grid;grid-template-columns:25px repeat(3,minmax(0,1fr));gap:6px;align-items:center;margin:6px 0}.series input{padding:9px 5px;text-align:center}.series small{text-align:center}.series .check{width:20px;height:20px}.history{border-top:1px solid #e5ece8;padding:8px 0}.history img{width:100px;border-radius:8px}.notice{background:#fff4dd;border-radius:10px;padding:11px;color:#76521c;font-size:13px}.tiny{font-size:12px}.bar{height:9px;background:#dae8e1;border-radius:99px;overflow:hidden}.bar span{display:block;background:#0b8d76;height:100%}.scroll{max-height:320px;overflow:auto}.exercise img{width:100%;max-width:285px;display:block;margin:7px auto}a{color:#086d60}#toast{position:fixed;bottom:82px;left:50%;transform:translateX(-50%);padding:12px;background:#102b2b;color:white;border-radius:12px;z-index:9;max-width:90%;text-align:center} @media(min-width:650px){.charts{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}}\n.ai-panel{background:#eef6f2;border:1px solid #d6e7df;border-radius:12px;padding:13px;margin:13px 0}.ai-panel h3{margin-top:0}.ai-result{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.55;margin:12px 0}.ai-result:empty{display:none}#aiReview{margin-top:12px}#aiReview table{width:100%;border-collapse:collapse;font-size:13px}#aiReview td{padding:6px;border-bottom:1px solid #d6e7df}#aiReview td:last-child{text-align:right;font-weight:650}#aiReview[hidden]{display:none}#aiChatResult article{padding:12px;background:#eef6f2;border-radius:12px;margin-bottom:8px}#aiChatResult article.user{background:#e7ecea}#aiToken{font-size:16px}button:focus-visible,input:focus-visible{outline:2px solid #087b70;outline-offset:2px}";
